using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — the SDK resolves IHttpClientFactory automatically.
/// DI-injected parameters never appear in the tool schema shown to LLMs.
/// </summary>
[McpServerToolType]
internal class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        return await client.GetStringAsync($"/posts/{id}", cancellationToken);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        return await client.GetStringAsync(url, cancellationToken);
    }

    [McpServerTool, Description("Create a new post with a title, body, and user ID.")]
    public async Task<string> CreatePost(
        [Description("Post title")] string title,
        [Description("Post body text")] string body,
        [Description("ID of the authoring user")] int userId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await client.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

